  "post:/api/sites/{siteId}/returns": {
    "fields": [
      {
        "name": "id",
        "type": "string"
      },
      {
        "name": "siteId",
        "type": "string"
      },
      {
        "name": "orderId",
        "type": "string",
        "note": "OrderID and OrderNumber are both carried: the id is the link, the number is what a merchant and a shopper both call it out loud."
      },
      {
        "name": "orderNumber",
        "type": "string"
      },
      {
        "name": "customerId",
        "type": "string",
        "note": "CustomerID is server-set from the session and never read from a request body — see the package doc."
      },
      {
        "name": "status",
        "type": "Status"
      },
      {
        "name": "reason",
        "type": "Reason"
      },
      {
        "name": "comment",
        "type": "string",
        "note": "Comment is the shopper's own words."
      },
      {
        "name": "lines",
        "type": "Line[]",
        "fields": [
          {
            "name": "productId",
            "type": "string"
          },
          {
            "name": "variantId",
            "type": "string"
          },
          {
            "name": "name",
            "type": "string"
          },
          {
            "name": "sku",
            "type": "string"
          },
          {
            "name": "quantity",
            "type": "number"
          },
          {
            "name": "priceCents",
            "type": "number"
          }
        ]
      },
      {
        "name": "staffNote",
        "type": "string",
        "note": "StaffNote is the merchant's own words — why they approved, refused, or refunded less than was asked."
      },
      {
        "name": "refundCents",
        "type": "number",
        "note": "RefundCents is what the merchant actually gave back, which is NOT necessarily what the lines are worth: a restocking fee, a partial goodwill refund, or shipping refunded on a merchant-fault return all make them differ."
      },
      {
        "name": "restocked",
        "type": "boolean",
        "note": "Restocked says the merchant judged the returned units sellable and put them back."
      },
      {
        "name": "source",
        "type": "string",
        "note": "Source is who filed the return: \"\" for a shopper or the manage screen, SourcePOS for a counter return — refunded through the drawer at the moment it is filed, which is why RefundedInWindow (the Z report's \"refunded outside the counter\"…"
      },
      {
        "name": "restockLocationId",
        "type": "string",
        "note": "RestockLocationID is the location the units go back onto the shelf at."
      },
      {
        "name": "createdAt",
        "type": "string (RFC3339)"
      },
      {
        "name": "updatedAt",
        "type": "string (RFC3339)"
      },
      {
        "name": "refundedAt",
        "type": "string (RFC3339) | null",
        "note": "RefundedAt is the instant the request FIRST became refunded — the date reports net a return on (POS P5), which updated_at cannot be (a later staff-note edit moves it)."
      }
    ],
    "source": "go",
    "goType": "returns.Request"
  },
